-- Product details from "Information For Website.xlsx": colours, full feature lists, and two new covers.
-- One-off for the live database. Run in Supabase › SQL Editor after schema.sql. Safe to re-run.
alter table public.products add column if not exists colors text[] not null default '{}' check (cardinality(colors) <= 10);
alter table public.products add column if not exists details text[] not null default '{}';

update public.products set name = 'DualTek + MagSafe', feat = '20 ft drop tested · Built-in corner bumpers · MagSafe', colors = array['White', 'Black']::text[], details = array['Ultra protective, 20 ft drop test certified', 'Patented design with built-in bumpers for extreme corner impact protection', 'Designed with shock-absorbing materials', 'Ergonomic grip support']::text[] where id = 'dualtek-2colour';
update public.products set name = 'Anti-Yellowing Case', feat = 'Anti-yellowing clear · Slim & lightweight · Metal buttons', colors = array['Clear', 'Black', 'Blue']::text[], details = array['Ultra-clear case, crafted using anti-yellowing materials', 'Lightweight and slim design', 'Easy to snap on and off', 'Functional metal buttons']::text[] where id = 'anti-yellowing';
update public.products set name = 'DualTek Studio + 360° Kickstand', feat = '20 ft drop tested · 360° kickstand · Frosted anti-fingerprint back', colors = array['Orange', 'Black', 'Blue', 'Burgundy']::text[], details = array['Ultra protective, 20 ft drop test certified', 'Stylish design with shock-absorbing materials', 'Translucent, frosted anti-fingerprint material', 'Built-in bumpers for extreme corner impact protection', 'Raised lip protects screen and camera lens from drops and bumps', 'Scratch-resistant and anti-slip grip']::text[] where id = 'dualtek-studio';
update public.products set name = 'Matte Case', feat = 'Minimal, sleek design · Slides into pockets · Tactile buttons', colors = array['Black']::text[], details = array['Minimal, sleek design', 'Effortlessly slides into pockets', 'Precision fit – simple to put on and remove', 'Raised edges protect screen from scratches and scuffs', 'Tactile buttons for seamless control']::text[] where id = 'matte';
update public.products set name = 'Liquid Silicone Case', feat = 'Premium liquid silicone · Microfiber lining · Slim & light', colors = array['Beige', 'Black', 'Blue']::text[], details = array['Premium silicone exterior – soft, smooth and comfortable to hold', 'Soft microfiber lining helps protect your phone from scratches, dust and daily wear', 'Slim and lightweight – adds protection without making your phone bulky']::text[] where id = 'silicone';

-- New covers. TODO: prices are placeholders and there are no photos yet: set both in /admin.
insert into public.products (id, num, code, kind, name, feat, badge, price, mrp, grams, def, imgs, colors, details, sort) values
  ('misttint', 131, 'MS', 'case', 'MistTint MagSafe Case', 'Gradient matte back · Metal camera ring · MagSafe', 'new', 899, 1499, 40, 0, '{}'::text[], array['Orange', 'Black', 'Blue', 'Burgundy']::text[], array['Made entirely of PC material – lightweight and slim', 'Metal camera ring and metal buttons for a premium, high-end feel', 'Gradient-coloured backplate with a matte, skin-friendly soft-touch finish']::text[], 152),
  ('lens-grip', 132, 'LP', 'case', 'Lens Grip MagSafe Case', 'Built-in lens stand & grip · Lens film included · MagSafe', 'new', 999, 1599, 40, 3, '{}'::text[], array['Blue', 'Clear']::text[], array['Made of PC and TPU; the clear version has an anti-fingerprint coating on the back to resist smudges', 'Built-in lens stand works as a phone kickstand or a handheld selfie grip', 'Comes with a lens film to protect the camera lens', 'HD tempered glass', 'Drop and scratch protection', 'Fingerprint and smudge resistant']::text[], 154)
on conflict (id) do nothing;
